 dict(name='Charge dash',tell='A dedicated lane warning precedes the committed line.',action='His secondary attack uses the native ram controller, rushing through the target lane before returning to cruising position.',response='Step out of the line after commitment, or evade through the dangerous pass.',facts=['Body collision threat','Straight committed rush','5.2 s base cooldown']),
