(W/'app.js').write_text('''"use strict";
let pilots=[],current;const $=s=>document.querySelector(s),video=$('#player');
function element(tag,text,cls){const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(cls)e.className=cls;return e;}
function chapterButtons(host,rows,target){host.replaceChildren();for(const c of rows){const b=element('button',c.label);b.type='button';b.dataset.time=c.t;b.addEventListener('click',async()=>{target.currentTime=c.t;try{await target.play();}catch{}});host.append(b);}target.ontimeupdate=()=>{let selected=-1;rows.forEach((c,i)=>{if(target.currentTime>=c.t-.1)selected=i;});[...host.children].forEach((b,i)=>b.setAttribute('aria-current',String(i===selected)));};}
function show(id,update=true){const p=pilots.find(q=>q.id===id)||pilots[0];current=p.id;video.pause();document.documentElement.style.setProperty('--accent',p.accent);$('#portrait').src='art/'+p.id+'-portrait.png';$('#portrait').alt=p.name+' in-game portrait';$('#ship-art').src='art/'+p.id+'-south.png';$('#ship-art').alt=p.ship+' actual game aircraft';$('#role').textContent=p.role;$('#name').textContent=p.name.toUpperCase();$('#ship').textContent=p.ship;$('#identity').textContent=p.identity;$('#quote').textContent='“'+p.quote+'”';$('#purpose').textContent=p.purpose;$('#flight').textContent=p.flight;video.src=p.video;video.poster=p.poster;video.setAttribute('aria-label',p.name+' native flight and attack preview');const track=element('track');track.kind='captions';track.srclang='en';track.label='Move labels';track.src='videos/'+p.id+'/moves.vtt';video.replaceChildren(track);$('#clip-label').textContent=p.name.toUpperCase()+' / FURIOUS / NATIVE MOVE PREVIEW';chapterButtons($('#chapters'),p.chapters,video);$('#attacks').replaceChildren();for(const a of p.attacks){const e=element('article',undefined,'attack');e.append(element('h3',a.name));const dl=element('dl');for(const [term,key]of[['Watch for','tell'],['Attack','action'],['Your response','response']])dl.append(element('dt',term),element('dd',a[key]));e.append(dl);const facts=element('div',undefined,'facts');for(const f of a.facts)facts.append(element('span',f));e.append(facts);$('#attacks').append(e);}for(const b of document.querySelectorAll('.pilot-button'))b.setAttribute('aria-pressed',String(b.dataset.pilot===p.id));if(update)history.replaceState(null,'','#'+p.id);}
fetch('data.json').then(r=>{if(!r.ok)throw Error('Pilot data did not load');return r.json()}).then(data=>{pilots=data;for(const p of pilots){const b=element('button',undefined,'pilot-button');b.type='button';b.dataset.pilot=p.id;b.setAttribute('aria-pressed','false');const im=element('img');im.src='art/'+p.id+'-portrait.png';im.alt='';const text=element('span');text.append(element('strong',p.name),element('small',p.ship));b.append(im,text);b.addEventListener('click',()=>show(p.id));$('#roster').append(b);}show(location.hash.slice(1),false);}).catch(e=>{$('#roster').textContent='Unable to load pilot files. Reload this page.';console.error(e);});
$('#replay').addEventListener('click',async()=>{video.currentTime=0;try{await video.play();}catch{}});window.addEventListener('hashchange',()=>{if(pilots.some(q=>q.id===location.hash.slice(1)))show(location.hash.slice(1),false);});
chapterButtons($('#formation-chapters'),[{t:1,label:'Star call'},{t:10,label:'Bowling call'},{t:19,label:'H call'},{t:28,label:'X call'}],$('#formation-video'));
document.addEventListener('play',e=>{if(e.target.tagName==='VIDEO')for(const v of document.querySelectorAll('video'))if(v!==e.target)v.pause();},true);
''',encoding='utf-8')
print('Built five-pilot interactive field guide')
